def closure(axioms: Iterable[str], negation: Dict[str, str]) -> FrozenSet[str]:
    known: Set[str] = set(axioms)
    agenda = list(known)
    while agenda:
        sentence = agenda.pop()
        result = negation[negation[sentence]]
        if result not in known:
            known.add(result)
            agenda.append(result)
    return frozenset(known)

def main() -> None:
    names = ["Liar", "Russell", "Berry", "Truth", "False", "Gap", "Certificate"]
    neg = dict(zip(names, ["Liar", "Russell", "Berry", "False", "Truth", "Gap", "Certificate"]))
    theorems = closure(["Liar", "Russell", "Berry", "Truth", "Certificate"], neg)
    print("Theorems:", sorted(theorems))
    print("Underivable:", sorted(set(names) - set(theorems)))

if __name__ == "__main__":
    main()

